from itertools import groupby


def group_by_length(words):
    result = {}
    for key, group in groupby(words, key=len):
        result[key] = list(group)
    return result


def consecutive_runs(items):
    result = []
    for key, group in groupby(items):
        result.append((key, sum(1 for _ in group)))
    return result


def group_by_key(items, key_fn):
    result = {}
    for key, group in groupby(items, key=key_fn):
        result[key] = list(group)
    return result
